'use strict';
(function(root){
const clone=x=>JSON.parse(JSON.stringify(x));
const defaults={Zinc:{unit:'t',capacity:50000,buffer:1000,growth:2,accounts:[{id:'A',name:'Account A',sector:'Galvanization',grade:'SHG',need:18000,share:60,booked:7000,eligible:true},{id:'B',name:'Account B',sector:'Infrastructure',grade:'SHG',need:12000,share:75,booked:6000,eligible:true},{id:'C',name:'Account C',sector:'Automotive',grade:'SHG',need:10000,share:65,booked:4000,eligible:true},{id:'D',name:'Account D',sector:'Steel',grade:'SHG',need:16000,share:75,booked:8000,eligible:true}]},Lead:{unit:'t',capacity:15000,buffer:300,growth:2,accounts:[{id:'E',name:'Account E',sector:'Automotive batteries',grade:'Refined',need:9000,share:55,booked:3000,eligible:true},{id:'F',name:'Account F',sector:'Industrial batteries',grade:'Refined',need:5000,share:70,booked:2000,eligible:true}]},Silver:{unit:'kg',capacity:15000,buffer:500,growth:2,accounts:[{id:'G',name:'Account G',sector:'Solar PV',grade:'Industrial',need:12000,share:50,booked:3500,eligible:true},{id:'H',name:'Account H',sector:'Electronics',grade:'Industrial',need:8000,share:50,booked:2500,eligible:true}]}};
const monthIndex=m=>{if(typeof m!=='string'||!/^\d{4}-(0[1-9]|1[0-2])$/.test(m))throw Error('Invalid planning month');const [y,n]=m.split('-').map(Number);return y*12+n-1;};
const finite=(v,l,h,name)=>{if(typeof v!=='number'||!Number.isFinite(v)||v<l||v>h)throw Error(name+' must be between '+l+' and '+h);return v;};
function validate(config,metal){if(!defaults[metal]||!config||config.unit!==defaults[metal].unit)throw Error('Metal / quantity unit mismatch');finite(config.capacity,1,1e9,'Capacity');finite(config.buffer,0,1e9,'Buffer');finite(config.growth,-30,30,'Growth');if(!Array.isArray(config.accounts)||!config.accounts.length||config.accounts.length>500)throw Error('Supply 1–500 customer records');const ids=new Set();for(const a of config.accounts){for(const k of ['id','name','sector','grade'])if(typeof a[k]!=='string'||!a[k].trim()||a[k].length>100)throw Error('Invalid customer '+k);if(ids.has(a.id))throw Error('Duplicate customer ID');ids.add(a.id);finite(a.need,0,1e9,'Requirement');finite(a.share,0,100,'HZL share');finite(a.booked,0,1e9,'Booked');if(typeof a.eligible!=='boolean')throw Error('Eligibility must be true or false');}return clone(config);}
function baseline(config,metal,months){const c=validate(config,metal);if(!Array.isArray(months)||months.length!==3)throw Error('Three monthly buckets required');const idx=months.map(monthIndex);if(idx.some((v,i)=>i&&v!==idx[i-1]+1))throw Error('Planning months must be consecutive');return months.map((month,i)=>{const offset=monthIndex(month)-monthIndex('2026-11');if(offset<0||offset>24)throw Error('Planning horizon outside supported window');const accounts=c.accounts.map(a=>{const need=Math.round(a.need*(1+c.growth/100)**offset),booked=Math.round(a.booked*[1,.65,.4][i]),potential=a.eligible?Math.round(need*a.share/100):0;return {...a,need,booked,potential,expected:Math.max(booked,potential),eligibilityException:!a.eligible&&booked>0,bookingException:booked>potential};});return {month,accounts,point:accounts.reduce((s,a)=>s+a.expected,0),booked:accounts.reduce((s,a)=>s+a.booked,0),need:accounts.reduce((s,a)=>s+a.need,0)};});}
function caseDefaults(metal,id){const sectors=defaults[metal].accounts.map(a=>a.sector),dis=id==='disruption';return {id,title:id==='baseline'?'Baseline':dis?'Disruption':'Opportunity',sectors:Object.fromEntries(sectors.map(s=>[s,id==='baseline'?0:metal==='Zinc'?(dis?(s==='Automotive'?-10:s==='Steel'?-5:0):(s==='Infrastructure'?10:s==='Galvanization'?5:0)):(dis?-5:5)])),profile:[1,.75,.5],referencePct:id==='baseline'?0:dis?5:-3,premiumShift:id==='baseline'?0:metal==='Silver'?(dis?5:-1):(dis?15:-10),freightShift:id==='baseline'?0:metal==='Silver'?(dis?1:-.5):(dis?30:-5),fxPct:id==='baseline'?0:dis?2:0,dutyDelta:id==='baseline'?0:dis?2:0,delay:id==='disruption'?14:0,origin:'All',rationale:id==='baseline'?'Unchanged customer baseline':'Illustrative sensitivity; validate coefficients and exposure before operational use'};}
function validateCase(s,c,pricing){if(!s||!['baseline','disruption','opportunity'].includes(s.id))throw Error('Invalid scenario');if(typeof s.rationale!=='string'||!s.rationale.trim()||s.rationale.length>1000)throw Error('Enter an assumption rationale');if(!Array.isArray(s.profile)||s.profile.length!==3)throw Error('Three transmission weights required');s.profile.forEach(v=>finite(v,0,1,'Monthly weight'));for(const [sector,v] of Object.entries(s.sectors||{})){if(!c.accounts.some(a=>a.sector===sector))throw Error('Scenario sector is absent from customer plan');finite(v,-50,50,'Sector sensitivity');}for(const k of ['referencePct','fxPct'])finite(s[k],-50,100,k);for(const k of ['premiumShift','freightShift'])finite(s[k],-1000,1000,k);finite(s.dutyDelta,-100,100,'Duty change');finite(s.delay,0,90,'Delay');if(!Number.isInteger(s.delay))throw Error('Delay must be whole days');if(typeof s.origin!=='string'||s.origin.length>100)throw Error('Invalid origin');if(pricing.premium+s.premiumShift<0||pricing.freight+s.freightShift<0)throw Error('Premium and freight cannot be negative');if(pricing.duty+s.dutyDelta<0||pricing.duty+s.dutyDelta>100)throw Error('Resulting duty must be 0–100%');return clone(s);}
function calculate(config,metal,months,scenario,pricing,cargo=[]){const c=validate(config,metal);for(const k of ['reference','premium','freight','depot'])finite(pricing[k],0,1e12,k);finite(pricing.fx,.001,1e6,'FX');finite(pricing.duty,0,100,'Duty');const s=validateCase(scenario,c,pricing),rows=baseline(c,metal,months).map((r,i)=>{const accounts=r.accounts.map(a=>{const adjusted=a.eligible?Math.round(a.potential*(1+(s.sectors[a.sector]||0)/100*s.profile[i])):0,expected=Math.max(a.booked,adjusted);return {...a,baseline:a.expected,expected,delta:expected-a.expected,protectedBooking:adjusted<a.booked};}),point=accounts.reduce((t,a)=>t+a.expected,0),domestic=Math.min(c.capacity,Math.max(point,r.booked)+c.buffer);return {...r,accounts,baselinePoint:r.point,point,delta:point-r.point,domestic,export:c.capacity-domestic,unserved:Math.max(0,Math.max(point,r.booked)-c.capacity),premium:pricing.premium+s.premiumShift};});const fx=pricing.fx*(1+s.fxPct/100),reference=pricing.reference*(1+s.referencePct/100),freight=pricing.freight+s.freightShift,duty=pricing.duty+s.dutyDelta,parity=(reference+pricing.premium+s.premiumShift+freight)*fx*(1+duty/100)+pricing.depot;const shipments=cargo.map(a=>{if(!/^\d{4}-\d{2}-\d{2}$/.test(a.eta)||!Number.isFinite(Date.parse(a.eta+'T00:00:00Z')))throw Error('Invalid cargo ETA');finite(a.quantity,0,1e12,'Cargo quantity');const d=new Date(a.eta+'T00:00:00Z');if(s.origin==='All'||s.origin===a.origin)d.setUTCDate(d.getUTCDate()+s.delay);return {...a,baselineEta:a.eta,eta:d.toISOString().slice(0,10)};});for(const r of rows){r.arrivals=shipments.filter(a=>a.eta.slice(0,7)===r.month).reduce((t,a)=>t+a.quantity,0);}return {metal,unit:c.unit,scenario:s,rows,pricing:{...pricing,reference,premium:pricing.premium+s.premiumShift,freight,fx,duty},parity,total:rows.reduce((t,r)=>t+r.point,0),shipments,arrivalsOutsideHorizon:shipments.filter(a=>!months.includes(a.eta.slice(0,7))).reduce((t,a)=>t+a.quantity,0)};}
const api={defaults:()=>clone(defaults),baseline,validate,caseDefaults,validateCase,calculate};if(typeof module!=='undefined'&&module.exports)module.exports=api;if(root)root.HZLCustomerEngine=api;
})(typeof window!=='undefined'?window:null);
